function eps = crossvalidation(Y,ins,oos)
    ins = Y(ins,:);
    oos = Y(oos,:);
    mdl = fitAR(ins,1,1);
    [~,eps1] = forecast(oos,mdl);
    mdl = fitAR(ins,1,2);
    [~,eps2] = forecast(oos,mdl);
    mdl = fitAR(ins,2,1);
    [~,eps3] = forecast(oos,mdl);
    mdl = fitAR(ins,2,2);
    [~,eps4] = forecast(oos,mdl);
    eps = [mean(eps1.^2);mean(eps2.^2);mean(eps3.^2);mean(eps4.^2)].’;
end
function mdl = fitAR(Y,p,d)
    for i = 1:d
        Y = diff(Y,1,1);
    end
    n = size(Y,1);
    mdl.p = p;
    mdl.d = d;
    mdl.beta = zeros(0,p+1);
    v = zeros(n-p,0);
    for y = Y
        A = ones(n-p,p+1);
        for i = 1:p
            A(:,i) = y(i:end-p-1+i);
        end
        mdl.beta(end+1,:) = A\y(p+1:end);
        v(:,end+1) = A*mdl.beta(end,:).’; %#ok<AGROW>
    end
    mdl.sigma = cov(Y(p+1:end,:)-v);
end
function [v,eps] = forecast(Y,mdl)
    assert(size(mdl.beta,1) == size(Y,2));
    assert(size(Y,1) > mdl.p+mdl.d);
    Y0 = Y;
    head = zeros(mdl.d,size(Y,2));
    for i = 1:mdl.d
        head(i,:) = Y(1,:);
        Y = diff(Y,1,1);
    end
    n = size(Y,1);
    v = zeros(n-mdl.p,0);
    for i = 1:size(Y,2)
        v(:,end+1) = conv(Y(1:end-1,i),mdl.beta(i,end-1:-1:1),’valid’)+mdl.beta(i,end); %#o
    end
    v = [Y(1:mdl.p,:);v];
    for i = mdl.d:-1:1
        v = cumsum([head(i,:);v],1);
    end



