function [vx,vy] = odefun(T,dTdx,dTdy,beta,v_max)
    delta_u = zeros(size(T));
    delta_u(T > 6) = -1;
    delta_u(T < 2) = 1;
    dT = sqrt(dTdx.^2+dTdy.^2);



